// 苍玄界：Cloudflare 创意工坊脚本
// 玩家端只保存公开 API 地址；管理员密钥只能放在 Cloudflare Worker Secret 中。
$(() => {
  const CX_WORKSHOP_BUILD_ID = 'cangxuan-workshop-cloudflare-v1.2.14-role-source-isolation';
  const CX_WORKSHOP_KEY = '__cangxuanCloudflareWorkshop__';
  const ROOT_ID = 'cx-workshop-cf-root';
  const STYLE_ID = 'cx-workshop-cf-style';
  const BUTTON_ID = 'cx-workshop-cf-button';
  const OVERLAY_ID = 'cx-workshop-cf-overlay';
  const MODAL_ID = 'cx-workshop-cf-modal';
  const FRAME_ID = 'cx-workshop-cf-frame';
  const API_STORAGE_KEY = 'cx-workshop-cloudflare-api-base';
  const POSITION_STORAGE_KEY = 'cx-workshop-cf-position';
  const SOURCE_TAG = 'cangxuan_workshop_cloudflare';
  const WORLDBOOK_NAME = '我的苍玄界，才不会这么跌宕起伏！';
  const CUSTOM_ROLE_STORAGE_KEY = 'cx_workshop_custom_roles_v1';
  const STATUS_ROLE_STORAGE_KEY = 'cx_status_custom_roles_v1';
  const STATUS_ROLE_SOURCE = 'cangxuan_status_custom_role';
  const USER_AVATAR_STORAGE_KEY = 'cx_status_user_avatar_v1';
  const CUSTOM_ROLE_CHAT_VAR = 'cx_workshop_custom_roles_prompt_v1';
  const CUSTOM_ROLE_PROMPT_ID = 'cx-workshop-custom-roles';
  const CUSTOM_ROLE_SYNC_EVENT = 'cx-status-custom-role-sync';
  const DIALOG_REGEX_SCRIPT_NAME = '对话美化（气泡版）';
  const DIALOG_AVATAR_BLOCK_START = '/* === 创意工坊人物头像绑定：开始 === */';
  const DIALOG_AVATAR_BLOCK_END = '/* === 创意工坊人物头像绑定：结束 === */';
  const VARIABLE_SCHEMA_SCRIPT_NAME = '变量结构';
  const VARIABLE_UPDATE_RULE_ENTRY_NAME = '[mvu_update]变量更新规则';
  const MISTAKEN_CUSTOM_ROLE_NAMES = ['小寒山'];

  // 这里写入正式 Worker 地址。这样导出角色卡时，创意工坊地址会跟着脚本一起保存。
  // UI 设置页仍可临时覆盖地址，但 localStorage 覆盖值不会进入导出的角色卡。
  const CX_WORKSHOP_DEFAULT_API_BASE = 'https://cangxuan-workshop.cangxuanjie.workers.dev';

  const KIND_OPTIONS = [
    ['continent', '大陆'],
    ['sea', '海域'],
    ['region', '区域'],
    ['settlement', '聚落'],
    ['sect', '宗门势力'],
    ['secret_realm', '秘境'],
    ['npc', '人物'],
    ['encounter', '遭遇'],
    ['resource', '资源'],
    ['quest_seed', '任务种子'],
  ];
  const KIND_LABELS = Object.fromEntries(KIND_OPTIONS);

  const hostWindow = window.parent && window.parent !== window ? window.parent : window;
  const hostDocument = hostWindow.document;
  const state = hostWindow[CX_WORKSHOP_KEY] || {
    initialized: false,
    modules: null,
    frameWindow: null,
  };
  hostWindow[CX_WORKSHOP_KEY] = state;

  function toast(type, message) {
    if (hostWindow.toastr && typeof hostWindow.toastr[type] === 'function') {
      hostWindow.toastr[type](message, '苍玄界创意工坊');
      return;
    }
    const logger = type === 'error' ? console.error : type === 'warning' ? console.warn : console.log;
    logger('[苍玄界创意工坊]', message);
  }

  function normalizeApiBase(value) {
    return String(value || '').trim().replace(/\/+$/, '');
  }

  function getApiBase() {
    let saved = '';
    try {
      saved = hostWindow.localStorage.getItem(API_STORAGE_KEY) || '';
    } catch (_) {}
    return normalizeApiBase(saved || CX_WORKSHOP_DEFAULT_API_BASE);
  }

  function setApiBase(value) {
    const normalized = normalizeApiBase(value);
    try {
      hostWindow.localStorage.setItem(API_STORAGE_KEY, normalized);
    } catch (_) {}
    state.modules = null;
    return normalized;
  }

  function readSavedPosition() {
    try {
      const raw = hostWindow.localStorage.getItem(POSITION_STORAGE_KEY);
      if (!raw) return null;
      const parsed = JSON.parse(raw);
      const left = Number(parsed?.left);
      const top = Number(parsed?.top);
      if (Number.isFinite(left) && Number.isFinite(top)) return { left, top };
    } catch (_) {}
    return null;
  }

  function savePosition(left, top) {
    try {
      hostWindow.localStorage.setItem(POSITION_STORAGE_KEY, JSON.stringify({ left, top }));
    } catch (_) {}
  }

  function getViewportSize() {
    const visual = hostWindow.visualViewport;
    return {
      width: Math.max(240, Number(visual?.width || hostWindow.innerWidth || hostDocument.documentElement.clientWidth || 1280)),
      height: Math.max(240, Number(visual?.height || hostWindow.innerHeight || hostDocument.documentElement.clientHeight || 720)),
    };
  }

  function clampPosition(left, top) {
    const size = 34;
    const { width, height } = getViewportSize();
    const maxLeft = Math.max(8, width - size - 8);
    const maxTop = Math.max(8, height - size - 8);
    return {
      left: Math.min(maxLeft, Math.max(8, Math.round(left))),
      top: Math.min(maxTop, Math.max(8, Math.round(top))),
    };
  }

  function positionRoot(root, left, top, shouldSave = false) {
    const next = clampPosition(left, top);
    root.style.left = `${next.left}px`;
    root.style.top = `${next.top}px`;
    root.style.right = 'auto';
    root.style.bottom = 'auto';
    if (shouldSave) savePosition(next.left, next.top);
  }

  function applyInitialPosition(root) {
    const saved = readSavedPosition();
    if (saved) {
      positionRoot(root, saved.left, saved.top, false);
      return;
    }
    const { width } = getViewportSize();
    positionRoot(root, width - 88 - 34, 18, false);
  }

  function installDrag(root, handle) {
    if (!root || !handle || handle.dataset.cxWorkshopDragBound === CX_WORKSHOP_BUILD_ID) return;
    handle.dataset.cxWorkshopDragBound = CX_WORKSHOP_BUILD_ID;
    handle.draggable = false;
    let dragState = null;
    const stop = event => {
      if (event?.cancelable) event.preventDefault();
      event?.stopPropagation?.();
    };
    const move = event => {
      if (!dragState || (dragState.pointerId != null && event.pointerId != null && event.pointerId !== dragState.pointerId)) return;
      const dx = event.clientX - dragState.startX;
      const dy = event.clientY - dragState.startY;
      if (!dragState.moved && Math.abs(dx) + Math.abs(dy) < 4) return;
      dragState.moved = true;
      root.dataset.cxDragged = '1';
      stop(event);
      positionRoot(root, dragState.left + dx, dragState.top + dy, true);
    };
    const up = event => {
      if (!dragState || (dragState.pointerId != null && event.pointerId != null && event.pointerId !== dragState.pointerId)) return;
      if (dragState.moved) {
        root.dataset.cxDragged = '1';
        hostWindow.setTimeout(() => {
          if (root.dataset.cxDragged === '1') root.dataset.cxDragged = '0';
        }, 160);
        stop(event);
      }
      if (dragState.pointerId != null) {
        try { handle.releasePointerCapture?.(dragState.pointerId); } catch (_) {}
      }
      hostWindow.removeEventListener('pointermove', move);
      hostWindow.removeEventListener('pointerup', up);
      hostWindow.removeEventListener('pointercancel', up);
      hostWindow.removeEventListener('mousemove', move);
      hostWindow.removeEventListener('mouseup', up);
      dragState = null;
    };
    const down = event => {
      if (event.button != null && event.button !== 0) return;
      const rect = root.getBoundingClientRect();
      dragState = {
        pointerId: event.pointerId,
        startX: event.clientX,
        startY: event.clientY,
        left: rect.left,
        top: rect.top,
        moved: false,
      };
      root.dataset.cxDragged = '0';
      if (event.pointerId != null) {
        try { handle.setPointerCapture?.(event.pointerId); } catch (_) {}
        hostWindow.addEventListener('pointermove', move, { passive: false });
        hostWindow.addEventListener('pointerup', up, { passive: false });
        hostWindow.addEventListener('pointercancel', up, { passive: false });
      } else {
        hostWindow.addEventListener('mousemove', move, { passive: false });
        hostWindow.addEventListener('mouseup', up, { passive: false });
      }
    };
    if (hostWindow.PointerEvent) {
      handle.addEventListener('pointerdown', down, { passive: false });
    } else {
      handle.addEventListener('mousedown', down, { passive: false });
    }
  }

  function bindWorkshopButton(root, button) {
    if (button.dataset.cxWorkshopBound === CX_WORKSHOP_BUILD_ID) {
      installDrag(root, button);
      return button;
    }
    const nextButton = button.cloneNode(true);
    nextButton.dataset.cxWorkshopBound = CX_WORKSHOP_BUILD_ID;
    delete nextButton.dataset.cxWorkshopDragBound;
    button.replaceWith(nextButton);
    nextButton.addEventListener('click', event => {
      event.preventDefault();
      event.stopPropagation();
      if (root.dataset.cxDragged === '1') {
        root.dataset.cxDragged = '0';
        return;
      }
      openWorkshop();
    });
    installDrag(root, nextButton);
    return nextButton;
  }

  function isApiConfigured() {
    const apiBase = getApiBase();
    return /^https?:\/\//i.test(apiBase) && !apiBase.includes('example.workers.dev') && !apiBase.includes('你的');
  }

  function getHelperFunction(name) {
    const helper = hostWindow.TavernHelper || window.TavernHelper || (typeof TavernHelper !== 'undefined' ? TavernHelper : null);
    if (helper && typeof helper[name] === 'function') return helper[name].bind(helper);
    if (typeof hostWindow[name] === 'function') return hostWindow[name].bind(hostWindow);
    if (typeof window[name] === 'function') return window[name].bind(window);
    try {
      if (typeof globalThis[name] === 'function') return globalThis[name].bind(globalThis);
    } catch (_) {}
    return null;
  }

  function requireHelper(methods) {
    const api = {};
    for (const method of methods) {
      const fn = getHelperFunction(method);
      if (!fn) throw new Error(`酒馆助手缺少 ${method} 接口`);
      api[method] = fn;
    }
    return api;
  }

  function asCleanText(value, maxLength = 160) {
    return String(value ?? '').replace(/[\u0000-\u001f\u007f]/g, '').trim().slice(0, maxLength);
  }

  function asCleanMultiline(value, maxLength = 6000) {
    return String(value ?? '')
      .replace(/\r\n?/g, '\n')
      .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '')
      .trim()
      .slice(0, maxLength);
  }

  function asWorldbookBody(value) {
    return String(value ?? '')
      .replace(/\r\n?/g, '\n')
      .replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, '')
      .trim()
      .slice(0, 900000);
  }

  function normalizeRemoteImageUrl(value) {
    const url = asCleanText(value, 2048);
    if (!url) return '';
    try {
      const parsed = new URL(url);
      if ((parsed.protocol === 'http:' || parsed.protocol === 'https:') && parsed.hostname) return url;
    } catch (_) {}
    return '';
  }

  function normalizePlayerAvatarValue(value) {
    const url = asCleanText(value, 900000);
    if (!url) return '';
    if (/^(https?:\/\/|data:image\/)/i.test(url)) return url;
    return '';
  }

  function cssStringValue(value) {
    return String(value || '').replace(/\\/g, '\\\\').replace(/"/g, '\\"').replace(/[\r\n]/g, ' ');
  }

  function cssUrlValue(value) {
    return String(value || '').replace(/\\/g, '\\\\').replace(/"/g, '%22').replace(/[\r\n]/g, '');
  }

  function escapeRegExp(value) {
    const specials = '\\^$.*+?()[]{}|/-';
    return Array.from(String(value || '')).map(char => specials.includes(char) ? '\\' + char : char).join('');
  }

  function roleAvatarUrl(role) {
    if (!role || typeof role !== 'object') return '';
    return normalizeRemoteImageUrl(role.defaultImg || role.avatar || role.avatarUrl || role.avatar_url || role.default_img || role.imageUrl || role.image_url || role.image || role.icon || role.portraitImg || role.portrait || role.portraitUrl || role.portrait_url);
  }

  function buildDialogueCustomRoleAvatarBlock(roles = loadCustomRoles()) {
    const css = (Array.isArray(roles) ? roles : [])
      .map(role => {
        const name = asCleanText(role.name || role.label, 80);
        const avatar = roleAvatarUrl(role);
        if (!name || !avatar) return '';
        const selectorName = cssStringValue(name);
        const url = cssUrlValue(avatar);
        return `.cxd-row[data-name="${selectorName}"] .cxd-avatar::after { content: "" !important; }\n.cxd-row[data-name="${selectorName}"] .cxd-avatar { background-image: url("${url}") !important; }`;
      })
      .filter(Boolean)
      .join('\n');
    if (!css) return '';
    return `${DIALOG_AVATAR_BLOCK_START}\n${css}\n${DIALOG_AVATAR_BLOCK_END}\n`;
  }

  function replaceDialogueAvatarBlock(replaceString, block) {
    const source = String(replaceString || '');
    const markerPattern = new RegExp(`${escapeRegExp(DIALOG_AVATAR_BLOCK_START)}[\\s\\S]*?${escapeRegExp(DIALOG_AVATAR_BLOCK_END)}\\n?`, 'g');
    const withoutOldBlock = source.replace(markerPattern, '');
    if (!block) return withoutOldBlock;
    if (withoutOldBlock.includes('</style>')) return withoutOldBlock.replace('</style>', `${block}</style>`);
    return `${withoutOldBlock}\n<style>\n${block}</style>`;
  }

  function tavernRegexName(regex) {
    return String(regex?.script_name ?? regex?.scriptName ?? '');
  }

  function tavernRegexReplaceString(regex) {
    return String(regex?.replace_string ?? regex?.replaceString ?? '');
  }

  function setTavernRegexReplaceString(regex, replaceString) {
    const next = { ...regex };
    if ('replace_string' in next || !('replaceString' in next)) next.replace_string = replaceString;
    if ('replaceString' in next) next.replaceString = replaceString;
    return next;
  }

  async function syncDialogueCustomRoleAvatarRegex(reason = 'workshop-custom-role') {
    const updateRegexes = getHelperFunction('updateTavernRegexesWith');
    if (typeof updateRegexes !== 'function') {
      console.warn('[苍玄界创意工坊] 酒馆助手缺少 updateTavernRegexesWith，无法写入对话美化头像');
      return false;
    }
    const block = buildDialogueCustomRoleAvatarBlock();
    let matched = false;
    let changed = false;
    try {
      await updateRegexes(regexes => {
        const list = Array.isArray(regexes) ? regexes : [];
        return list.map(regex => {
          if (tavernRegexName(regex) !== DIALOG_REGEX_SCRIPT_NAME) return regex;
          matched = true;
          const before = tavernRegexReplaceString(regex);
          const after = replaceDialogueAvatarBlock(before, block);
          if (after === before) return regex;
          changed = true;
          return setTavernRegexReplaceString(regex, after);
        });
      }, { type: 'character', name: 'current' });
      if (!matched) console.warn('[苍玄界创意工坊] 未找到对话美化头像绑定目标正则', reason);
      else if (!changed) console.info('[苍玄界创意工坊] 对话美化头像绑定无需更新', reason);
      return changed;
    } catch (error) {
      console.warn('[苍玄界创意工坊] 写入对话美化头像绑定失败', error);
      return false;
    }
  }
  function queueDialogueCustomRoleAvatarRegexSync(reason = 'workshop-custom-role') {
    try {
      if (state.avatarRegexSyncTimer) hostWindow.clearTimeout(state.avatarRegexSyncTimer);
      state.avatarRegexSyncTimer = hostWindow.setTimeout(() => {
        state.avatarRegexSyncTimer = null;
        syncDialogueCustomRoleAvatarRegex(reason);
      }, 250);
      return true;
    } catch (error) {
      console.warn('[苍玄界创意工坊] 排队写入对话美化头像失败', error);
      syncDialogueCustomRoleAvatarRegex(reason);
      return false;
    }
  }

  function normalizeCustomRole(role) {
    if (!role || typeof role !== 'object') return null;
    const name = asCleanText(role.name || role.label, 40);
    const defaultImg = normalizeRemoteImageUrl(role.defaultImg || role.default_img || role.avatar || role.avatarUrl || role.avatar_url || role.imageUrl || role.image_url || role.image || role.icon);
    const portraitImg = normalizeRemoteImageUrl(role.portraitImg || role.portrait_img || role.portrait || role.portraitUrl || role.portrait_url || role.coverUrl || role.cover_url || defaultImg);
    const sect = asCleanText(role.sect || role.group || '自定义', 40) || '自定义';
    const profile = asCleanMultiline(role.profile || role.lore || role.setting || role.description || role.prompt || role.promptText || '', 12000);
    if (!name || !defaultImg) return null;
    const moduleId = asCleanText(role.moduleId || role.module_id || '', 120);
    const entryId = asCleanText(role.entryId || role.entry_id || '', 120);
    return { name, defaultImg, portraitImg: portraitImg || defaultImg, sect, profile, custom: true, source: 'workshop', moduleId, entryId };
  }

  function workshopRoleKey(role) {
    return [role?.moduleId || '', role?.entryId || '', role?.name || ''].join('::');
  }

  function getEffectiveCustomRoles(roles = loadCustomRoles()) {
    const roleMap = new Map();
    (Array.isArray(roles) ? roles : []).forEach(role => {
      const normalized = normalizeCustomRole(role);
      if (normalized) roleMap.set(normalized.name, normalized);
    });
    return [...roleMap.values()];
  }

  function loadStatusbarManualRoles() {
    try {
      const parsed = JSON.parse(hostWindow.localStorage.getItem(STATUS_ROLE_STORAGE_KEY) || '[]');
      return Array.isArray(parsed) ? parsed.map(role => normalizeCustomRole(role)).filter(Boolean) : [];
    } catch (_) {
      return [];
    }
  }

  function getMvuObj() {
    return hostWindow.Mvu || window.Mvu || (typeof Mvu !== 'undefined' ? Mvu : null);
  }

  function isPlainObject(value) {
    return value !== null && typeof value === 'object' && !Array.isArray(value);
  }

  function loadCustomRoles() {
    try {
      const parsed = JSON.parse(hostWindow.localStorage.getItem(CUSTOM_ROLE_STORAGE_KEY) || '[]');
      if (!Array.isArray(parsed)) return [];
      const roleMap = new Map();
      parsed.forEach(role => {
        const normalized = normalizeCustomRole(role);
        if (normalized) roleMap.set(workshopRoleKey(normalized), normalized);
      });
      return [...roleMap.values()];
    } catch (_) {
      return [];
    }
  }

  function notifyStatusbarExternalRoles() {
    const api = getStatusbarRoleApi();
    if (!api || typeof api.syncExternal !== 'function') return false;
    try {
      const result = api.syncExternal();
      if (result && typeof result.catch === 'function') result.catch(() => {});
      return true;
    } catch (_) {
      return false;
    }
  }

  function saveCustomRoles(roles) {
    const roleMap = new Map();
    (Array.isArray(roles) ? roles : []).forEach(role => {
      const normalized = normalizeCustomRole(role);
      if (normalized) roleMap.set(workshopRoleKey(normalized), normalized);
    });
    const normalizedRoles = [...roleMap.values()].filter(role => !MISTAKEN_CUSTOM_ROLE_NAMES.includes(role.name));
    try { hostWindow.localStorage.setItem(CUSTOM_ROLE_STORAGE_KEY, JSON.stringify(normalizedRoles)); } catch (_) {}
    queueDialogueCustomRoleAvatarRegexSync('workshop-save-custom-roles');
    notifyStatusbarExternalRoles();
    broadcastCustomRoleSync('workshop-save-custom-roles');
    syncCustomRolesToChatVariables();
    injectCustomRolePrompt();
    return normalizedRoles;
  }

  function isManualRoleWorldbookEntry(entry, roleName) {
    const name = asCleanText(roleName, 40);
    const source = String(entry?.extra?.source || '');
    if (source === SOURCE_TAG) return false;
    const sourceName = asCleanText(entry?.extra?.custom_role_name || '', 40);
    const entryName = asCleanText(entry?.name || entry?.comment || '', 40);
    const keys = Array.isArray(entry?.keys) ? entry.keys.map(value => asCleanText(value, 80)).filter(Boolean) : [];
    if (source === STATUS_ROLE_SOURCE) return sourceName === name || entryName === name;
    if (source) return false;
    return entryName === '自定义NPC_' + name || (entryName === name && keys.length === 1 && keys[0] === name);
  }

  async function migrateLegacySharedWorkshopRoles() {
    const getNames = getHelperFunction('getWorldbookNames');
    const getWorldbook = getHelperFunction('getWorldbook');
    if (typeof getNames !== 'function' || typeof getWorldbook !== 'function') return false;
    const names = await getNames();
    if (!Array.isArray(names) || !names.includes(WORLDBOOK_NAME)) return false;
    const worldbook = await getWorldbook(WORLDBOOK_NAME);
    const entries = Array.isArray(worldbook) ? worldbook : [];
    const workshopEntries = entries.filter(entry => entry?.extra?.source === SOURCE_TAG && entry?.extra?.custom_role);
    if (!workshopEntries.length) return false;
    let legacyRoles = [];
    try {
      const parsed = JSON.parse(hostWindow.localStorage.getItem(STATUS_ROLE_STORAGE_KEY) || '[]');
      if (Array.isArray(parsed)) legacyRoles = parsed;
    } catch (_) {}
    if (!legacyRoles.length) return false;
    const legacyByName = new Map();
    legacyRoles.forEach(role => {
      const normalized = normalizeCustomRole(role);
      if (normalized) legacyByName.set(normalized.name, role);
    });
    const workshopRoles = loadCustomRoles();
    const existingKeys = new Set(workshopRoles.map(workshopRoleKey));
    const movedNames = new Set();
    let added = 0;
    workshopEntries.forEach(entry => {
      const roleName = asCleanText(entry?.extra?.custom_role_name || entry?.name || entry?.comment || '', 40);
      const legacyRole = legacyByName.get(roleName);
      if (!legacyRole) return;
      const migrated = normalizeCustomRole({
        ...legacyRole,
        moduleId: String(entry?.extra?.module_id || ''),
        entryId: String(entry?.extra?.workshop_entry_id || entry?.uid || roleName),
      });
      if (!migrated) return;
      const identity = workshopRoleKey(migrated);
      if (!existingKeys.has(identity)) {
        existingKeys.add(identity);
        workshopRoles.push(migrated);
        added += 1;
      }
      if (!entries.some(candidate => isManualRoleWorldbookEntry(candidate, roleName))) movedNames.add(roleName);
    });
    if (added > 0) saveCustomRoles(workshopRoles);
    if (movedNames.size > 0) {
      const keptLegacyRoles = legacyRoles.filter(role => !movedNames.has(asCleanText(role?.name, 40)));
      try { hostWindow.localStorage.setItem(STATUS_ROLE_STORAGE_KEY, JSON.stringify(keptLegacyRoles)); } catch (_) {}
      notifyStatusbarExternalRoles();
    }
    return added > 0 || movedNames.size > 0;
  }

  function loadUserAvatarUrl() {
    try { return normalizePlayerAvatarValue(hostWindow.localStorage.getItem(USER_AVATAR_STORAGE_KEY) || ''); } catch (_) { return ''; }
  }

  function getDefaultNpcRecord(role) {
    return {
      宗门: role?.sect || '自定义',
      境界: '未知',
      当前所在地: '未知',
      好感度数值: 0,
      好感度阶段: '形同陌路',
      关系标签: '初识',
      新增互动输入: '',
      最近互动记录: ['暂无'],
    };
  }

  function mergeNpcRecord(existing, role) {
    return { ...getDefaultNpcRecord(role), ...(isPlainObject(existing) ? existing : {}) };
  }

  function broadcastCustomRoleSync(reason = 'workshop') {
    const detail = { reason, roles: getEffectiveCustomRoles(), userAvatar: loadUserAvatarUrl() };
    try { hostWindow.dispatchEvent(new CustomEvent(CUSTOM_ROLE_SYNC_EVENT, { detail })); } catch (_) {}
    try { window.dispatchEvent(new CustomEvent(CUSTOM_ROLE_SYNC_EVENT, { detail })); } catch (_) {}
  }

  function buildCustomRolePromptText(roles = getEffectiveCustomRoles()) {
    if (!roles.length) return '';
    const lines = roles.map(role => `- ${role.name}（${role.sect || '自定义'}）：创意工坊自定义主要 NPC；可写入 /人际交往/结识道友录 与 /人际交往/当前接触人物；不得降级写入 /人际交往/路遇道友录。`);
    return ['创意工坊自定义主要 NPC 白名单：'].concat(lines).join('\n');
  }

  function injectCustomRolePrompt() {
