  async function syncCustomRoleToLatestMvu(role) {
    const normalized = normalizeCustomRole(role);
    if (!normalized) return false;
    const mvuObj = getMvuObj();
    if (!mvuObj || typeof mvuObj.getMvuData !== 'function' || typeof mvuObj.replaceMvuData !== 'function') return false;
    try {
      const data = mvuObj.getMvuData({ type: 'message', message_id: -1 });
      if (!data || typeof data !== 'object') return false;
      if (!isPlainObject(data.stat_data)) data.stat_data = {};
      if (!isPlainObject(data.stat_data.人际交往)) data.stat_data.人际交往 = {};
      if (!isPlainObject(data.stat_data.人际交往.结识道友录)) data.stat_data.人际交往.结识道友录 = {};
      data.stat_data.人际交往.结识道友录[normalized.name] = mergeNpcRecord(data.stat_data.人际交往.结识道友录[normalized.name], normalized);
      if (isPlainObject(data.stat_data.人际交往.路遇道友录) && Object.prototype.hasOwnProperty.call(data.stat_data.人际交往.路遇道友录, normalized.name)) {
        delete data.stat_data.人际交往.路遇道友录[normalized.name];
      }
      await mvuObj.replaceMvuData(data, { type: 'message', message_id: -1 });
      return true;
    } catch (error) {
      console.warn('[苍玄界创意工坊] 自定义角色写入最新 MVU 变量失败', error);
      return false;
    }
  }

  function upsertNameInJsStringArray(content, constName, roleName) {
    const cleanName = asCleanText(roleName, 40);
    if (!cleanName || typeof content !== 'string') return content;
    const pattern = new RegExp('(const\\s+' + constName + '\\s*=\\s*\\[)([\\s\\S]*?)(\\n\\s*\\];)');
    return content.replace(pattern, (full, head, body, tail) => {
      const names = [...body.matchAll(/"([^"\\]*(?:\\.[^"\\]*)*)"/g)]
        .map(match => {
          try { return JSON.parse(`"${match[1]}"`); } catch (_) { return match[1]; }
        })
        .filter(Boolean);
      if (names.includes(cleanName)) return full;
      names.push(cleanName);
      return `${head}\n${names.map(name => `    ${JSON.stringify(name)},`).join('\n')}${tail}`;
    });
  }

  async function syncCustomRoleToVariableSchema(role) {
    const normalized = normalizeCustomRole(role);
    if (!normalized) return false;
    const updateScripts = getHelperFunction('updateScriptTreesWith');
    if (typeof updateScripts !== 'function') return false;
    let touched = false;
    const visit = trees => (Array.isArray(trees) ? trees : []).map(tree => {
      if (tree && tree.type === 'folder' && Array.isArray(tree.scripts)) return { ...tree, scripts: visit(tree.scripts) };
      if (!tree || tree.type !== 'script' || typeof tree.content !== 'string' || tree.name !== VARIABLE_SCHEMA_SCRIPT_NAME) return tree;
      const nextContent = upsertNameInJsStringArray(tree.content, 'MAIN_NPC_NAMES', normalized.name);
      if (nextContent !== tree.content) {
        touched = true;
        return { ...tree, content: nextContent };
      }
      return tree;
    });
    try {
      await updateScripts(trees => visit(trees), { type: 'character' });
      return touched;
    } catch (error) {
      console.warn('[苍玄界创意工坊] 自定义角色写入 MAIN_NPC_NAMES 失败', error);
      return false;
    }
  }

  function upsertRoleNameInVariableRuleContent(content, roleName) {
    const cleanName = asCleanText(roleName, 40);
    if (!cleanName || typeof content !== 'string') return content;
    const appendName = namesText => {
      const names = String(namesText || '').split('、').map(name => name.trim()).filter(Boolean);
      if (!names.includes(cleanName)) names.push(cleanName);
      return names.join('、');
    };
    let next = content;
    next = next.replace(/(- 主要 NPC 名单：)([^；\n]*)(；[^\n]*)?/, (full, head, namesText, tail = '；状态栏或创意工坊保存的自定义角色也按主要 NPC 处理') => {
      return `${head}${appendName(namesText)}${tail}`;
    });
    next = next.replace(/(#### 白名单 NPC\s*\n)([\s\S]*?)(\n\n#### 更新规则)/, (full, head, body, tail) => {
      const exists = body.split(/\r?\n/).some(line => line.trim() === `- ${cleanName}`);
      if (exists) return full;
      return `${head}${body.trimEnd()}\n- ${cleanName}${tail}`;
    });
    next = next.replace(/(- 主要 NPC 仅允许写入 \/人际交往\/结识道友录：)([^；\n]*)(；以及(?:状态栏“角色图像”页|创意工坊)保存的自定义角色。)/, (full, head, namesText) => {
      return `${head}${appendName(namesText)}；以及创意工坊保存的自定义角色。`;
    });
    return next;
  }

  async function syncCustomRoleToWorldbookRules(role) {
    const normalized = normalizeCustomRole(role);
    if (!normalized) return false;
    const updateWorldbook = getHelperFunction('updateWorldbookWith');
    if (typeof updateWorldbook !== 'function') return false;
    let touched = false;
    try {
      await updateWorldbook(WORLDBOOK_NAME, worldbook => (Array.isArray(worldbook) ? worldbook : []).map(entry => {
        const content = String(entry?.content || '');
        const entryName = entry?.name || entry?.comment || '';
        const isTarget = entryName === VARIABLE_UPDATE_RULE_ENTRY_NAME
          || (content.includes('变量更新规则:') && content.includes('当前接触人物:') && content.includes('主要 NPC 名单'))
          || (content.includes('### 3.3 当前接触人物') && content.includes('#### 白名单 NPC') && content.includes('#### 3.4 道友收录白名单与分流规则'));
        if (!isTarget) return entry;
        const nextContent = upsertRoleNameInVariableRuleContent(content, normalized.name);
        if (nextContent !== content) {
          touched = true;
          return { ...entry, content: nextContent };
        }
        return entry;
      }), { render: 'debounced' });
      return touched;
    } catch (error) {
      console.warn('[苍玄界创意工坊] 自定义角色写入变量更新规则失败', error);
      return false;
    }
  }

  function removeNameFromJsStringArray(content, constName, roleNames) {
    const namesToRemove = new Set((Array.isArray(roleNames) ? roleNames : [roleNames]).map(name => asCleanText(name, 40)).filter(Boolean));
    if (!namesToRemove.size || typeof content !== 'string') return content;
    const pattern = new RegExp('(const\\s+' + constName + '\\s*=\\s*\\[)([\\s\\S]*?)(\\n\\s*\\];)');
    return content.replace(pattern, (full, head, body, tail) => {
      const names = [...body.matchAll(/"([^"\\]*(?:\\.[^"\\]*)*)"/g)]
        .map(match => {
          try { return JSON.parse(`"${match[1]}"`); } catch (_) { return match[1]; }
        })
        .filter(name => name && !namesToRemove.has(name));
      return `${head}\n${names.map(name => `    ${JSON.stringify(name)},`).join('\n')}${tail}`;
    });
  }

  async function removeCustomRolesFromVariableSchema(roleNames) {
    const names = (Array.isArray(roleNames) ? roleNames : [roleNames]).map(name => asCleanText(name, 40)).filter(Boolean);
    if (!names.length) return false;
    const updateScripts = getHelperFunction('updateScriptTreesWith');
    if (typeof updateScripts !== 'function') return false;
    let touched = false;
    const visit = trees => (Array.isArray(trees) ? trees : []).map(tree => {
      if (tree && tree.type === 'folder' && Array.isArray(tree.scripts)) return { ...tree, scripts: visit(tree.scripts) };
      if (!tree || tree.type !== 'script' || typeof tree.content !== 'string' || tree.name !== VARIABLE_SCHEMA_SCRIPT_NAME) return tree;
      const nextContent = removeNameFromJsStringArray(tree.content, 'MAIN_NPC_NAMES', names);
      if (nextContent !== tree.content) {
        touched = true;
        return { ...tree, content: nextContent };
      }
      return tree;
    });
    try {
      await updateScripts(trees => visit(trees), { type: 'character' });
      return touched;
    } catch (error) {
      console.warn('[苍玄界创意工坊] 自定义角色移除 MAIN_NPC_NAMES 失败', error);
      return false;
    }
  }

  function removeRoleNamesInVariableRuleContent(content, roleNames) {
    const namesToRemove = new Set((Array.isArray(roleNames) ? roleNames : [roleNames]).map(name => asCleanText(name, 40)).filter(Boolean));
    if (!namesToRemove.size || typeof content !== 'string') return content;
    let next = content;
    next = next.replace(/(#### 白名单 NPC\s*\n)([\s\S]*?)(\n\n#### 更新规则)/, (full, head, body, tail) => {
      const lines = body.split(/\r?\n/).filter(line => {
        const item = line.trim().replace(/^-\s*/, '');
        return !namesToRemove.has(item);
      });
      return `${head}${lines.join('\n').trimEnd()}${tail}`;
    });
    next = next.replace(/(- 主要 NPC 仅允许写入 \/人际交往\/结识道友录：)([^；\n]*)(；以及(?:状态栏“角色图像”页|创意工坊)保存的自定义角色。)/, (full, head, namesText, tail) => {
      const names = namesText.split('、').map(name => name.trim()).filter(name => name && !namesToRemove.has(name));
      return `${head}${names.join('、')}${tail}`;
    });
    return next;
  }

