  }

  function removeRoleNamesFromRelationState(data, roleNames) {
    const namesToRemove = new Set((Array.isArray(roleNames) ? roleNames : [roleNames]).map(name => asCleanText(name, 40)).filter(Boolean));
    if (!namesToRemove.size || !data || typeof data !== 'object') return false;
    const relation = data.stat_data?.人际交往 || data.人际交往;
    if (!isPlainObject(relation)) return false;
    let touched = false;
    ['结识道友录', '当前接触人物', '路遇道友录'].forEach(key => {
      if (!isPlainObject(relation[key])) return;
      namesToRemove.forEach(name => {
        if (Object.prototype.hasOwnProperty.call(relation[key], name)) {
          delete relation[key][name];
          touched = true;
        }
      });
    });
    return touched;
  }

  async function removeCustomRolesFromMvuMessages(roleNames) {
    const names = (Array.isArray(roleNames) ? roleNames : [roleNames]).map(name => asCleanText(name, 40)).filter(Boolean);
    if (!names.length) return false;
    const mvuObj = getMvuObj();
    if (!mvuObj || typeof mvuObj.getMvuData !== 'function' || typeof mvuObj.replaceMvuData !== 'function') return false;
    const ids = [-1, 'latest'];
    try {
      const currentId = getHelperFunction('getCurrentMessageId')?.();
      const lastId = getHelperFunction('getLastMessageId')?.();
      [currentId, lastId].forEach(id => {
        if (id !== null && id !== undefined && id !== '') ids.push(id);
      });
    } catch (_) {}
    let touchedAny = false;
    for (const id of [...new Set(ids.map(id => String(id)))]) {
      const messageId = id === '-1' ? -1 : id;
      try {
        const data = mvuObj.getMvuData({ type: 'message', message_id: messageId });
        if (!data || typeof data !== 'object') continue;
        if (!removeRoleNamesFromRelationState(data, names)) continue;
        await mvuObj.replaceMvuData(data, { type: 'message', message_id: messageId });
        touchedAny = true;
      } catch (_) {}
    }
    return touchedAny;
  }

  function removeCustomRolesFromChatVariables(roleNames) {
    const namesToRemove = new Set((Array.isArray(roleNames) ? roleNames : [roleNames]).map(name => asCleanText(name, 40)).filter(Boolean));
    if (!namesToRemove.size) return false;
    const updateVars = getHelperFunction('updateVariablesWith');
    if (typeof updateVars !== 'function') return false;
    try {
      updateVars(variables => {
        const next = variables && typeof variables === 'object' ? variables : {};
        const payload = next[CUSTOM_ROLE_CHAT_VAR];
        if (payload && typeof payload === 'object') {
          payload.roles = Array.isArray(payload.roles)
            ? payload.roles.filter(role => !namesToRemove.has(asCleanText(role?.name || role?.label, 40)))
            : [];
          payload.updatedAt = Date.now();
        }
        return next;
      }, { type: 'chat' });
      return true;
    } catch (error) {
      console.warn('[苍玄界创意工坊] 自定义角色聊天变量清理失败', error);
      return false;
    }
  }

  function removeCustomRolesFromLocalCaches(roleNames) {
    const namesToRemove = new Set((Array.isArray(roleNames) ? roleNames : [roleNames]).map(name => asCleanText(name, 40)).filter(Boolean));
    if (!namesToRemove.size) return false;
    let touched = false;
    try {
      const raw = hostWindow.localStorage.getItem(CUSTOM_ROLE_STORAGE_KEY);
      const parsed = raw ? JSON.parse(raw) : [];
      if (Array.isArray(parsed)) {
        const kept = parsed.filter(role => !namesToRemove.has(asCleanText(role?.name || role?.label, 40)));
        if (kept.length !== parsed.length) {
          hostWindow.localStorage.setItem(CUSTOM_ROLE_STORAGE_KEY, JSON.stringify(kept));
          touched = true;
        }
      }
    } catch (_) {}
    ['mvu_npc_order'].forEach(key => {
      try {
        const parsed = JSON.parse(hostWindow.localStorage.getItem(key) || '[]');
        if (!Array.isArray(parsed)) return;
        const kept = parsed.filter(name => !namesToRemove.has(asCleanText(name, 40)));
        if (kept.length !== parsed.length) {
          hostWindow.localStorage.setItem(key, JSON.stringify(kept));
          touched = true;
        }
      } catch (_) {}
    });
    try {
      const records = JSON.parse(hostWindow.localStorage.getItem('mvu_npc_records') || '{}');
      if (isPlainObject(records)) {
        namesToRemove.forEach(name => {
          if (Object.prototype.hasOwnProperty.call(records, name)) {
            delete records[name];
            touched = true;
          }
        });
        hostWindow.localStorage.setItem('mvu_npc_records', JSON.stringify(records));
      }
    } catch (_) {}
    try {
      const cache = JSON.parse(hostWindow.localStorage.getItem('mvu_new_badge_cache') || '{}');
      if (isPlainObject(cache)) {
        ['daoist', 'minorDaoist'].forEach(category => {
          if (!isPlainObject(cache[category])) return;
          namesToRemove.forEach(name => {
            if (Object.prototype.hasOwnProperty.call(cache[category], name)) {
              delete cache[category][name];
              touched = true;
            }
          });
        });
        hostWindow.localStorage.setItem('mvu_new_badge_cache', JSON.stringify(cache));
      }
    } catch (_) {}
    return touched;
  }

