  async function removeCustomRolesFromLatestMvu(roleNames) {
    const namesToRemove = new Set((Array.isArray(roleNames) ? roleNames : [roleNames]).map(name => asCleanText(name, 40)).filter(Boolean));
    if (!namesToRemove.size) return false;
    const mvuObj = getMvuObj();
    if (!mvuObj || typeof mvuObj.getMvuData !== 'function' || typeof mvuObj.replaceMvuData !== 'function') return false;
