  function removeCustomRolesFromLocalOrder(roleNames) {
    const namesToRemove = new Set((Array.isArray(roleNames) ? roleNames : [roleNames]).map(name => asCleanText(name, 40)).filter(Boolean));
    if (!namesToRemove.size) return false;
    try {
      const order = JSON.parse(hostWindow.localStorage.getItem('mvu_npc_order') || '[]');
      if (!Array.isArray(order)) return false;
      const nextOrder = order.filter(name => !namesToRemove.has(String(name || '')));
      if (nextOrder.length === order.length) return false;
      hostWindow.localStorage.setItem('mvu_npc_order', JSON.stringify(nextOrder));
      return true;
    } catch (_) {
      return false;
    }
  }

  async function removeCustomRolesByNames(roleNames) {
    const names = [...new Set((Array.isArray(roleNames) ? roleNames : [roleNames]).map(name => asCleanText(name, 40)).filter(Boolean))];
    if (!names.length) return { removed: 0, names: [] };
    const nameSet = new Set(names);
    const roles = loadCustomRoles();
    const keptRoles = roles.filter(role => !nameSet.has(role.name));
    const removed = roles.length - keptRoles.length;
    if (removed > 0) saveCustomRoles(keptRoles);
    const remainingWorkshopNames = new Set(getEffectiveCustomRoles(keptRoles).map(role => role.name));
    const manualNames = new Set(loadStatusbarManualRoles().map(role => role.name));
    const cleanupNames = names.filter(name => !remainingWorkshopNames.has(name) && !manualNames.has(name));
    const results = {
      removed,
      names,
      cleanupNames,
      order: removeCustomRolesFromLocalOrder(cleanupNames),
      localCaches: removeCustomRolesFromLocalCaches(cleanupNames),
      chatVariables: removeCustomRolesFromChatVariables(cleanupNames),
      statusbar: await removeCustomRolesFromStatusbarApi(),
      latestMvu: await removeCustomRolesFromLatestMvu(cleanupNames),
      variableSchema: await removeCustomRolesFromVariableSchema(cleanupNames),
      variableRules: await removeCustomRolesFromWorldbookRules(cleanupNames),
    };
    syncCustomRolesToChatVariables();
    injectCustomRolePrompt();
    broadcastCustomRoleSync('workshop-remove-custom-role');
    return results;
  }

  function makeCustomNpcTag(roleName) {
    const encoded = Array.from(String(roleName || 'custom')).map(char => char.codePointAt(0).toString(16)).join('_');
    return `npc_custom_${encoded || 'role'}`;
  }

  function makePromptTagName(value) {
    const text = String(value || 'workshop_entry')
      .replace(/[<>\s\/"'`=]+/g, '_')
      .replace(/^_+|_+$/g, '')
      .slice(0, 80);
    return text || 'workshop_entry';
  }

  function hasOuterPromptTag(text) {
    const body = String(text || '').trim();
    const match = body.match(/^<([^>\s/]+)>[\s\S]*<\/\1>\s*$/);
    return !!match;
  }

  function wrapWorldbookBody(label, body) {
    const clean = asWorldbookBody(body);
    if (!clean) return '';
    if (hasOuterPromptTag(clean)) return clean;
    const tag = makePromptTagName(label);
    return `<${tag}>\n${clean}\n</${tag}>`;
  }

  function buildCustomRoleWorldbookContent(role) {
    const normalized = normalizeCustomRole(role);
    if (!normalized) return '';
    return wrapWorldbookBody(normalized.name, normalized.profile || `${normalized.name}:`);
  }

  function isCustomRoleWorldbookEntry(entry, roleName) {
    const cleanName = asCleanText(roleName, 40);
    const entryName = String(entry?.name || entry?.comment || '').trim();
    const content = String(entry?.content || '');
    return entryName === cleanName
      || entryName === `自定义NPC_${cleanName}`
      || content.includes(`姓名: ${cleanName}`)
      || content.includes(`<${makeCustomNpcTag(cleanName)}>`);
  }

