      },
      keys,
      secondary_keys: [],
      logic: 'and_any',
      filters: [],
      constant: false,
      selective: true,
      position: { type: 'before_character_definition', role: 'system', depth: 4, order: 100 },
      content: buildCustomRoleWorldbookContent(normalized),
      use_regex: true,
      insertion_order: 100,
      probability: 100,
      recursion: { prevent_incoming: true, prevent_outgoing: true, delay_until: null },
      effect: { sticky: null, cooldown: null, delay: null },
      extensions: {
        position: 0,
        exclude_recursion: true,
        probability: 100,
        useProbability: true,
        depth: 4,
        selectiveLogic: 0,
        outlet_name: '',
        group: '',
        group_override: false,
        group_weight: 100,
        prevent_recursion: true,
        delay_until_recursion: false,
        scan_depth: null,
        match_whole_words: null,
        use_group_scoring: false,
        case_sensitive: null,
        automation_id: '',
        role: 0,
        vectorized: false,
        sticky: null,
        cooldown: null,
        delay: null,
        match_persona_description: false,
        match_character_description: false,
        match_character_personality: false,
        match_character_depth_prompt: false,
        match_scenario: false,
        match_creator_notes: false,
        triggers: [],
        ignore_budget: false,
      },
      extra: { source: SOURCE_TAG, kind: 'npc', custom_role: true },
    };
  }

  async function upsertCustomRoleWorldbookEntry(role) {
    const normalized = normalizeCustomRole(role);
    const entryPayload = buildCustomRoleWorldbookEntry(normalized);
    if (!normalized || !entryPayload) return false;
    await ensureWorldbook();
    const updateWorldbook = getHelperFunction('updateWorldbookWith');
    const createEntries = getHelperFunction('createWorldbookEntries');
    if (typeof updateWorldbook !== 'function') return false;
    let existed = false;
    try {
      await updateWorldbook(WORLDBOOK_NAME, worldbook => (Array.isArray(worldbook) ? worldbook : []).map(entry => {
        if (!isCustomRoleWorldbookEntry(entry, normalized.name)) return entry;
        existed = true;
        return { ...entry, ...entryPayload, uid: entry.uid };
      }), { render: 'debounced' });
      if (!existed && typeof createEntries === 'function') {
        await createEntries(WORLDBOOK_NAME, [entryPayload], { render: 'debounced' });
      }
      return true;
    } catch (error) {
      console.warn('[苍玄界创意工坊] 自定义角色世界书条目写入失败', error);
      return false;
    }
  }

  function getStatusbarRoleApi() {
    if (hostWindow.CangXuanStatusbarRoles) return hostWindow.CangXuanStatusbarRoles;
    try {
      const frame = hostDocument.getElementById('cx-floating-status-frame');
      if (frame?.contentWindow?.CangXuanStatusbarRoles) return frame.contentWindow.CangXuanStatusbarRoles;
    } catch (_) {}
    return null;
  }

  async function syncWorkshopCustomRole(role) {
    const normalized = normalizeCustomRole(role);
    if (!normalized) return { ok: false, reason: 'invalid' };
    const identity = workshopRoleKey(normalized);
    const roles = loadCustomRoles().filter(item => workshopRoleKey(item) !== identity);
    roles.push(normalized);
    saveCustomRoles(roles);
    try {
      let savedOrder = JSON.parse(hostWindow.localStorage.getItem('mvu_npc_order') || '[]');
      if (!Array.isArray(savedOrder)) savedOrder = [];
      savedOrder = savedOrder.filter(name => name !== normalized.name);
      savedOrder.unshift(normalized.name);
      hostWindow.localStorage.setItem('mvu_npc_order', JSON.stringify(savedOrder));
    } catch (_) {}

    const results = {
      latestMvu: await syncCustomRoleToLatestMvu(normalized),
      variableSchema: await syncCustomRoleToVariableSchema(normalized),
      variableRules: await syncCustomRoleToWorldbookRules(normalized),
    };
    notifyStatusbarExternalRoles();
    syncCustomRolesToChatVariables();
    injectCustomRolePrompt();
    broadcastCustomRoleSync('workshop-custom-role');
    return { ok: true, role: normalized, via: 'workshop', results };
  }

  function extractCustomRolesFromModule(moduleInfo) {
    const entries = Array.isArray(moduleInfo?.content?.entries) ? moduleInfo.content.entries : [];
    const roles = [];
    for (const entry of entries) {
      const entryKind = String(entry?.kind || moduleInfo?.kind || '');
      if (entryKind !== 'npc') continue;
      const entryTitle = entry?.label || entry?.name || moduleInfo?.title;
      const entryBody = entryWorldbookText(entry || {}, moduleInfo || {}, null, entryTitle);
      const rawRole = entry?.customRole || entry?.custom_role || null;
      const fallback = {
        name: entryTitle,
        sect: entry?.sect || entry?.group || moduleInfo?.authorName || '自定义',
        profile: entryBody || entry?.profile || entry?.description || moduleInfo?.description || '',
        avatar: entry?.avatar || entry?.avatarUrl || entry?.avatar_url || entry?.defaultImg || entry?.default_img || entry?.imageUrl || entry?.image_url || entry?.image || entry?.icon || moduleInfo?.previewUrl,
        portrait: entry?.portrait || entry?.portraitUrl || entry?.portrait_url || entry?.portraitImg || entry?.portrait_img || entry?.coverUrl || entry?.cover_url || moduleInfo?.previewUrl,
      };
      const roleSource = isPlainObject(rawRole)
        ? { ...rawRole, profile: entryBody || rawRole.profile || rawRole.lore || rawRole.setting || rawRole.description || '' }
        : fallback;
      const normalized = normalizeCustomRole({
        ...roleSource,
        moduleId: String(moduleInfo?.id || ''),
        entryId: String(entry?.id || entryTitle || ''),
      });
      if (normalized) roles.push(normalized);
    }
    return roles;
  }

  async function syncCustomRolesFromModule(moduleInfo) {
    const roles = extractCustomRolesFromModule(moduleInfo);
    const results = [];
    for (const role of roles) results.push(await syncWorkshopCustomRole(role));
    return results;
  }

  function splitEntryList(value) {
    if (Array.isArray(value)) return value.map(item => String(item || '').trim()).filter(Boolean);
    if (typeof value === 'string') return value.split(/[\n,，、；;]+/).map(item => item.trim()).filter(Boolean);
    return [];
  }

  function firstTextValue(values) {
    for (const value of values) {
      if (typeof value !== 'string') continue;
      const clean = asWorldbookBody(value);
      if (clean) return clean;
    }
    return '';
  }

  function entryPrimaryKeys(entry, moduleInfo, customRole, title) {
    const keys = [
      ...splitEntryList(entry.keys),
      ...splitEntryList(entry.key),
      ...splitEntryList(entry.primary_keys),
      ...splitEntryList(entry.primaryKeys),
      ...splitEntryList(entry.keywords),
      ...splitEntryList(entry.keyword),
      ...splitEntryList(entry.triggers),
      ...splitEntryList(entry.triggerKeys),
      ...splitEntryList(entry.trigger_keys),
      ...splitEntryList(entry.promptKeys),
      ...splitEntryList(entry.prompt_keys),
      ...splitEntryList(entry.activationKeys),
      ...splitEntryList(entry.activation_keys),
      ...splitEntryList(entry.worldbookKeys),
      ...splitEntryList(entry.worldbook_keys),
    ];
    if (!keys.length && customRole?.name) keys.push(customRole.name);
    if (!keys.length && title) keys.push(title);
    if (!keys.length && moduleInfo?.title) keys.push(moduleInfo.title);
    return [...new Set(keys.map(item => asCleanText(item, 80)).filter(Boolean))];
  }

  function entrySecondaryKeys(entry) {
    const rawSecondary = entry.keys_secondary || entry.keysecondary || entry.keysSecondary || entry.secondary_keys || entry.secondaryKeys || {};
    const keys = [
      ...splitEntryList(rawSecondary.keys),
      ...splitEntryList(rawSecondary.key),
      ...splitEntryList(rawSecondary),
      ...splitEntryList(entry.secondary),
      ...splitEntryList(entry.secondary_keys),
      ...splitEntryList(entry.secondaryKeys),
    ];
    return [...new Set(keys.map(item => asCleanText(item, 80)).filter(Boolean))];
  }

  function entrySecondaryLogic(entry) {
    const rawSecondary = entry.keys_secondary || entry.keysecondary || entry.keysSecondary || {};
    const logic = rawSecondary.logic || entry.secondaryLogic || entry.secondary_logic || entry.logic || 'and_any';
    return ['and_any', 'and_all', 'not_all', 'not_any'].includes(logic) ? logic : 'and_any';
  }

  function entryWorldbookText(entry, moduleInfo, customRole, title) {
    return firstTextValue([
      entry.yamlText,
      entry.yaml_text,
      entry.yaml,
      entry.prompt,
      entry.promptText,
      entry.prompt_text,
      entry.content,
      entry.body,
      entry.worldbook,
      entry.text,
      entry.lore,
      entry.setting,
      entry.description,
      customRole?.profile,
      entry.profile,
      moduleInfo?.description,
      title ? `${title}:` : '',
    ]);
  }

  async function apiFetch(path, options = {}) {
    if (!isApiConfigured()) throw new Error('请先在“设置”里填写 Cloudflare Worker 地址');
    const response = await fetch(`${getApiBase()}${path}`, {
      cache: 'no-store',
      ...options,
      headers: {
        'Content-Type': 'application/json',
        ...(options.headers || {}),
      },
    });
    const data = await response.json().catch(() => ({}));
    if (!response.ok) throw new Error(data.error || `请求失败：HTTP ${response.status}`);
    return data;
  }

  async function loadModules(force) {
    if (state.modules && !force) return state.modules;
    const data = await apiFetch('/api/cultivation-world/modules?page_size=100');
    state.modules = Array.isArray(data.modules) ? data.modules : [];
    return state.modules;
  }

  async function downloadModule(moduleId) {
    const data = await apiFetch(`/api/cultivation-world/modules/${encodeURIComponent(moduleId)}/download`);
    return data.module || data;
  }

  async function submitModule(submission) {
    return apiFetch('/api/cultivation-world/submissions', {
      method: 'POST',
      body: JSON.stringify(submission),
    });
  }

  function toWorldbookEntry(entry, moduleInfo) {
    const moduleId = String(moduleInfo.id || entry.sourceModuleId || '');
    const entryId = String(entry.id || `${moduleId}-entry`);
    const kind = String(entry.kind || moduleInfo.kind || 'region');
    const title = entry.label || entry.name || moduleInfo.title || `工坊条目 ${entryId}`;
    const rawCustomRole = entry.customRole || entry.custom_role || (kind === 'npc' ? {
      name: title,
      sect: entry.sect || entry.group || moduleInfo.authorName || '自定义',
      avatar: entry.avatar || entry.avatarUrl || entry.avatar_url || entry.defaultImg || entry.default_img || entry.imageUrl || entry.image_url || entry.image || entry.icon || moduleInfo.previewUrl,
      portrait: entry.portrait || entry.portraitUrl || entry.portrait_url || entry.portraitImg || entry.portrait_img || entry.coverUrl || entry.cover_url || moduleInfo.previewUrl,
      profile: entry.profile || entry.description || moduleInfo.description || '',
    } : null);
    const customRole = normalizeCustomRole(rawCustomRole);
    const isNpc = kind === 'npc' && !!customRole;
    const keys = entryPrimaryKeys(entry, moduleInfo, customRole, title);
    const secondaryKeys = entrySecondaryKeys(entry);
    const secondaryLogic = entrySecondaryLogic(entry);
    const bodyText = entryWorldbookText(entry, moduleInfo, customRole, title);
    return {
      name: title,
      comment: title,
      enabled: true,
      type: 'selective',
      strategy: {
        type: 'selective',
        keys,
        keys_secondary: {
          logic: secondaryLogic,
          keys: secondaryKeys,
        },
        scan_depth: 'same_as_global',
      },
      keys,
      secondary_keys: secondaryKeys,
      logic: secondaryLogic,
      filters: [],
      constant: false,
      selective: true,
      position: {
        type: 'before_character_definition',
        role: 'system',
        depth: 4,
        order: 100,
      },
      content: wrapWorldbookBody(title, bodyText),
      use_regex: true,
      insertion_order: 100,
      probability: 100,
      recursion: {
        prevent_incoming: true,
        prevent_outgoing: true,
        delay_until: null,
      },
      effect: {
        sticky: null,
        cooldown: null,
        delay: null,
      },
      extensions: {
        position: 0,
        exclude_recursion: true,
        probability: 100,
        useProbability: true,
        depth: 4,
        selectiveLogic: 0,
        outlet_name: '',
        group: '',
        group_override: false,
        group_weight: 100,
        prevent_recursion: true,
        delay_until_recursion: false,
        scan_depth: null,
        match_whole_words: null,
        use_group_scoring: false,
        case_sensitive: null,
        automation_id: '',
        role: 0,
        vectorized: false,
        sticky: null,
        cooldown: null,
        delay: null,
        match_persona_description: false,
        match_character_description: false,
        match_character_personality: false,
        match_character_depth_prompt: false,
        match_scenario: false,
        match_creator_notes: false,
        triggers: [],
        ignore_budget: false,
      },
      extra: {
        source: SOURCE_TAG,
        module_id: moduleId,
        workshop_entry_id: entryId,
        kind,
        custom_role: isNpc,
        custom_role_name: isNpc ? customRole.name : '',
      },
    };
  }

  async function ensureWorldbook() {
    const api = requireHelper(['getWorldbookNames', 'createWorldbook']);
    const names = await api.getWorldbookNames();
    if (!Array.isArray(names) || !names.includes(WORLDBOOK_NAME)) {
      await api.createWorldbook(WORLDBOOK_NAME);
    }
  }

  async function scanInstalled(modules) {
    const installed = {};
    let names = [];
    try {
      const api = requireHelper(['getWorldbookNames', 'getWorldbook']);
      names = await api.getWorldbookNames();
      if (!Array.isArray(names) || !names.includes(WORLDBOOK_NAME)) return installed;
      const entries = await api.getWorldbook(WORLDBOOK_NAME);
      const ids = new Set((entries || [])
        .filter(entry => entry.extra && entry.extra.source === SOURCE_TAG && entry.extra.module_id)
        .map(entry => String(entry.extra.module_id)));
      const currentIds = new Set((modules || []).map(moduleInfo => String(moduleInfo.id)));
      for (const moduleInfo of modules || []) installed[moduleInfo.id] = ids.has(String(moduleInfo.id));
      installed.__orphanIds = [...ids].filter(id => !currentIds.has(id));
    } catch (error) {
      console.warn('[苍玄界创意工坊] 扫描已订阅模块失败', error);
    }
    return installed;
  }

  async function installModule(moduleId) {
    const api = requireHelper(['deleteWorldbookEntries', 'createWorldbookEntries']);
    await ensureWorldbook();
    const moduleInfo = await downloadModule(moduleId);
    const entries = Array.isArray(moduleInfo.content?.entries) ? moduleInfo.content.entries : [];
    if (entries.length === 0) throw new Error('该模块没有可写入的世界书条目');

    await api.deleteWorldbookEntries(
      WORLDBOOK_NAME,
      entry => entry.extra && entry.extra.source === SOURCE_TAG && String(entry.extra.module_id) === String(moduleInfo.id),
      { render: 'debounced' },
    );
    await api.createWorldbookEntries(
      WORLDBOOK_NAME,
      entries.map(entry => toWorldbookEntry(entry, moduleInfo)),
      { render: 'immediate' },
    );
    const roleSync = await syncCustomRolesFromModule(moduleInfo);
    const roleCount = roleSync.filter(item => item?.ok).length;
    return `已订阅「${moduleInfo.title}」，写入 ${entries.length} 条世界书${roleCount ? `，同步 ${roleCount} 名主要 NPC` : ''}`;
  }

  async function syncSubmissionLocally(submission) {
    const moduleInfo = {
      id: `local-${Date.now().toString(36)}`,
      title: submission?.title || '本地投稿',
      kind: submission?.kind || 'region',
      authorName: submission?.authorName || 'SillyTavern 玩家',
      description: submission?.description || '',
      content: submission?.content || { entries: [] },
    };
    const roleSync = await syncCustomRolesFromModule(moduleInfo);
    return roleSync.filter(item => item?.ok).length;
  }

  function extractCustomRoleNamesFromEntries(entries) {
    const names = new Set();
    (Array.isArray(entries) ? entries : []).forEach(entry => {
      const extra = entry?.extra || {};
      if (extra.source !== SOURCE_TAG) return;
      const extraName = asCleanText(extra.custom_role_name || extra.role_name || extra.npc_name || '', 40);
      if (extraName) {
        names.add(extraName);
        return;
      }
      if (extra.custom_role || extra.kind === 'npc') {
        const entryName = asCleanText(entry?.name || entry?.comment || '', 40);
        if (entryName) names.add(entryName);
        const content = String(entry?.content || '');
        const nameMatch = content.match(/姓名\s*[:：]\s*([^\n\r]+)/);
        if (nameMatch) names.add(asCleanText(nameMatch[1], 40));
      }
    });
    return [...names].filter(Boolean);
  }

  async function uninstallModule(moduleId) {
    const api = requireHelper(['getWorldbookNames', 'getWorldbook', 'deleteWorldbookEntries']);
    const names = await api.getWorldbookNames();
    if (!Array.isArray(names) || !names.includes(WORLDBOOK_NAME)) return '本地没有工坊世界书，无需清理';
    const beforeEntries = await api.getWorldbook(WORLDBOOK_NAME);
    const targetEntries = (Array.isArray(beforeEntries) ? beforeEntries : [])
      .filter(entry => entry.extra && entry.extra.source === SOURCE_TAG && String(entry.extra.module_id) === String(moduleId));
    const roleNameSet = new Set(extractCustomRoleNamesFromEntries(targetEntries));
    try {
      const moduleInfo = await downloadModule(moduleId);
      extractCustomRolesFromModule(moduleInfo).forEach(role => roleNameSet.add(role.name));
    } catch (_) {}
    const remainingEntries = (Array.isArray(beforeEntries) ? beforeEntries : [])
      .filter(entry => entry.extra && entry.extra.source === SOURCE_TAG && String(entry.extra.module_id) !== String(moduleId));
    const remainingRoleNames = new Set(extractCustomRoleNamesFromEntries(remainingEntries));
    const removableRoleNames = [...roleNameSet].filter(name => !remainingRoleNames.has(name));
    const result = await api.deleteWorldbookEntries(
      WORLDBOOK_NAME,
      entry => entry.extra && entry.extra.source === SOURCE_TAG && String(entry.extra.module_id) === String(moduleId),
      { render: 'immediate' },
    );
    const count = Array.isArray(result?.deleted_entries) ? result.deleted_entries.length : 0;
    const cleanup = await removeCustomRolesByNames(removableRoleNames);
    const roleCount = cleanup?.names?.length || 0;
    return `已取消订阅，清理 ${count} 条世界书${roleCount ? `，移除 ${roleCount} 名主要 NPC` : ''}`;
  }

  async function cleanupOrphanModules(moduleIds) {
    const ids = new Set((Array.isArray(moduleIds) ? moduleIds : []).map(id => String(id || '')).filter(Boolean));
    if (!ids.size) return '没有需要清理的已下架模块';
    const api = requireHelper(['getWorldbookNames', 'getWorldbook', 'deleteWorldbookEntries']);
    const names = await api.getWorldbookNames();
    if (!Array.isArray(names) || !names.includes(WORLDBOOK_NAME)) return '本地没有工坊世界书，无需清理';
    const beforeEntries = await api.getWorldbook(WORLDBOOK_NAME);
    const targetEntries = (Array.isArray(beforeEntries) ? beforeEntries : [])
      .filter(entry => entry.extra && entry.extra.source === SOURCE_TAG && ids.has(String(entry.extra.module_id)));
    const remainingEntries = (Array.isArray(beforeEntries) ? beforeEntries : [])
      .filter(entry => entry.extra && entry.extra.source === SOURCE_TAG && !ids.has(String(entry.extra.module_id)));
    const remainingRoleNames = new Set(extractCustomRoleNamesFromEntries(remainingEntries));
    const removableRoleNames = extractCustomRoleNamesFromEntries(targetEntries).filter(name => !remainingRoleNames.has(name));
    const result = await api.deleteWorldbookEntries(
      WORLDBOOK_NAME,
      entry => entry.extra && entry.extra.source === SOURCE_TAG && ids.has(String(entry.extra.module_id)),
      { render: 'immediate' },
    );
    const count = Array.isArray(result?.deleted_entries) ? result.deleted_entries.length : 0;
    const cleanup = await removeCustomRolesByNames(removableRoleNames);
    const roleCount = cleanup?.names?.length || 0;
    return `已清理 ${count} 条已下架模块世界书${roleCount ? `，移除 ${roleCount} 名主要 NPC` : ''}`;
  }

  function postToFrame(type, payload) {
    const frame = hostDocument.getElementById(FRAME_ID);
    const frameWindow = frame?.contentWindow || state.frameWindow;
    if (!frameWindow) return;
    frameWindow.postMessage({ type, payload }, '*');
  }

  async function sendState(force) {
    postToFrame('cx_workshop_config', {
      apiBase: getApiBase(),
      configured: isApiConfigured(),
      worldbookName: WORLDBOOK_NAME,
      kinds: KIND_OPTIONS,
    });
    if (!isApiConfigured()) {
