            + '<p>' + esc(item.description || '无简介') + '</p></div>'
            + itemActions + '</div>'
            + '<div class="meta"><span>作者：' + esc(item.authorName || '匿名') + '</span><span>下载：' + esc(item.downloadCount || 0) + ' 次</span><span class="meta-id">ID: ' + esc(item.id) + '</span></div>'
            + '</div></div></article>';
