      }
      function isNpcSubmission() {
        return valueOf('submit-kind') === 'npc';
      }
      function updateNpcRoleFields() {
        var panel = byId('npc-role-fields');
        if (!panel) return;
        panel.style.display = isNpcSubmission() ? 'grid' : 'none';
        byId('submit-content').placeholder = isNpcSubmission()
          ? '必填；只写投稿正文，系统最多只在外层补一组 <角色名> 标签，不会补人物模板。'
          : '<工坊条目>\\n工坊条目:\\n  定位: ...\\n</工坊条目>';
      }
      function makeCustomNpcTag(roleName) {
        var encoded = Array.from(String(roleName || 'custom')).map(function(char) {
          return char.codePointAt(0).toString(16);
        }).join('_');
        return 'npc_custom_' + (encoded || 'role');
      }
      function cleanMultiline(value, maxLength) {
        return String(value || '').replace(/\\r\\n?/g, '\\n').trim().slice(0, maxLength || 12000);
      }
      function makePromptTagName(value) {
        var tag = String(value || 'workshop_entry')
          .replace(/[<>\\s\\/"'=]+/g, '_')
          .replace(/^_+|_+$/g, '')
          .slice(0, 80);
        return tag || 'workshop_entry';
      }
      function hasOuterPromptTag(text) {
        return /^<([^>\\s/]+)>[\\s\\S]*<\\/\\1>\\s*$/.test(String(text || '').trim());
      }
      function wrapWorldbookText(label, body) {
        var clean = cleanMultiline(body, 900000);
        if (!clean) return '';
        if (hasOuterPromptTag(clean)) return clean;
        var tag = makePromptTagName(label);
        return '<' + tag + '>\\n' + clean + '\\n</' + tag + '>';
      }
      function requireRemoteImageUrl(id, label) {
        var url = normalizeRemoteImageUrl(valueOf(id));
        if (!url) throw new Error(label + '必须填写 http:// 或 https:// 图床链接');
        return url;
      }
      function setRolePreview(kind, value) {
        var url = normalizeRemoteImageUrl(value);
        var preview = byId(kind === 'avatar' ? 'role-avatar-preview' : 'role-portrait-preview');
        if (!preview) return;
        if (url) {
          preview.src = url;
          preview.classList.remove('empty');
        } else {
          preview.removeAttribute('src');
          preview.classList.add('empty');
        }
      }
      function buildSubmission() {
        var title = valueOf('submit-title');
        var kind = valueOf('submit-kind') || 'region';
        var label = valueOf('submit-label') || title;
        var rawWorldbookText = valueOf('submit-content');
        var yamlText = rawWorldbookText;
        if (!title) throw new Error('请填写标题');
        var keys = splitTags(valueOf('submit-keys'));
        if (!keys.length) throw new Error('请填写绿灯触发关键词/提示词');
        var customRole = null;
        if (kind === 'npc') {
          var avatar = requireRemoteImageUrl('role-avatar-url', '人物模块头像');
          var portrait = requireRemoteImageUrl('role-portrait-url', '人物模块立绘');
          var roleName = title;
          if (!roleName) throw new Error('人物模块需要角色名');
          customRole = {
            name: roleName,
            sect: valueOf('role-sect') || '自定义',
            avatar: avatar,
            portrait: portrait,
            profile: rawWorldbookText || valueOf('role-profile') || valueOf('submit-description') || '',
          };
        }
        if (!yamlText) throw new Error('请填写世界书正文');
        yamlText = wrapWorldbookText(label || title, yamlText);
        var entry = {
          id: makeId(label),
          kind: kind,
          label: label,
          keys: keys,
          keys_secondary: { logic: 'and_any', keys: [] },
          yamlText: yamlText,
          tags: []
