        if (customRole) entry.customRole = customRole;
        var submissionPreviewUrl = customRole ? customRole.portrait : '';
        return {
          schema: 'cultivation_world_module_submission_v1',
          title: title,
          kind: kind,
          previewUrl: submissionPreviewUrl,
          authorName: valueOf('submit-author') || 'SillyTavern 玩家',
          description: valueOf('submit-description'),
          tags: [],
