      function copyDraft() {
        var text = byId('submit-json').value || JSON.stringify(renderDraft(), null, 2);
        if (navigator.clipboard && navigator.clipboard.writeText) return navigator.clipboard.writeText(text);
        byId('submit-json').focus();
        byId('submit-json').select();
        document.execCommand('copy');
        return Promise.resolve();
      }
      window.addEventListener('message', function(event) {
        var data = event.data || {};
        if (data.type === 'cx_workshop_config') {
          state.apiBase = data.payload.apiBase || '';
          state.configured = !!data.payload.configured;
          state.kinds = data.payload.kinds || [];
          state.worldbookName = data.payload.worldbookName || '';
          byId('api-base').value = state.apiBase;
          renderKinds();
          renderModules();
        } else if (data.type === 'cx_workshop_catalog') {
          state.modules = data.payload.modules || [];
          state.installed = data.payload.installed || {};
          state.source = data.payload.source || '';
          renderModules();
        } else if (data.type === 'cx_workshop_busy') {
          setStatus(data.payload.message || '处理中...', 'busy');
        } else if (data.type === 'cx_workshop_result') {
          setStatus(data.payload.message || '完成', data.payload.success ? 'ok' : 'error');
          if (data.payload.success && data.payload.clearSubmit) {
            clearSubmitForm();
            setTab('browse');
          }
        } else if (data.type === 'cx_workshop_error') {
          setStatus(data.payload.message || '发生错误', 'error');
        }
      });
      document.addEventListener('click', async function(event) {
        var button = event.target.closest('button[data-action]');
        if (!button) return;
        var action = button.dataset.action;
        try {
          if (action === 'tab') {
            setTab(button.dataset.tabTarget);
          } else if (action === 'refresh') {
            post('cx_workshop_refresh');
          } else if (action === 'install' || action === 'uninstall') {
            post('cx_workshop_' + action, { moduleId: button.dataset.id });
          } else if (action === 'cleanup-orphans') {
            post('cx_workshop_cleanup_orphans', { moduleIds: state.installed.__orphanIds || [] });
          } else if (action === 'save-api') {
