            setStatus('投稿 JSON 已复制。', 'ok');
          } else if (action === 'submit') {
            var submission = byId('submit-json').value.trim() ? JSON.parse(byId('submit-json').value) : renderDraft();
            post('cx_workshop_submit', { submission: submission });
          }
        } catch (error) {
          setStatus(error.message || String(error), 'error');
        }
      });
      byId('search').addEventListener('input', renderModules);
      byId('filter-kind').addEventListener('change', renderModules);
      byId('submit-kind').addEventListener('change', updateNpcRoleFields);
      ['role-avatar-url', 'role-portrait-url'].forEach(function(id) {
