        .cx-workshop-cf-head {
          height: 46px; flex-basis: 46px; min-height: 46px; padding: 0 10px;
        }
        .cx-workshop-cf-head strong {
          min-width: 0; font-size: 13px; letter-spacing: 2px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
        }
        .cx-workshop-cf-seal { width: 24px; height: 24px; font-size: 13px; }
        .cx-workshop-cf-close { flex: 0 0 auto; min-width: 74px; padding: 7px 9px; letter-spacing: 1px; }
      }
    `;
    hostDocument.head.appendChild(style);
  }

  function ensureDom() {
    ensureStyle();
    let root = hostDocument.getElementById(ROOT_ID);
    if (!root) {
      root = hostDocument.createElement('div');
      root.id = ROOT_ID;
      hostDocument.body.appendChild(root);
    }
    let button = root.querySelector(`#${BUTTON_ID}`);
    if (!button) {
      button = hostDocument.createElement('button');
      button.id = BUTTON_ID;
      button.type = 'button';
      button.title = '苍玄界创意工坊';
      button.textContent = '坊';
      root.appendChild(button);
    }
    applyInitialPosition(root);
    bindWorkshopButton(root, button);

    let overlay = hostDocument.getElementById(OVERLAY_ID);
    if (!overlay) {
      overlay = hostDocument.createElement('div');
      overlay.id = OVERLAY_ID;
      overlay.innerHTML = `
        <div id="${MODAL_ID}">
          <div class="cx-workshop-cf-head">
            <strong><span class="cx-workshop-cf-seal">坊</span>苍玄界创意工坊</strong>
            <button class="cx-workshop-cf-close" type="button">✕ 关闭</button>
          </div>
          <iframe id="${FRAME_ID}" sandbox="allow-scripts allow-same-origin allow-forms allow-popups"></iframe>
        </div>
      `;
      hostDocument.body.appendChild(overlay);
      overlay.addEventListener('click', event => {
        if (event.target === overlay || event.target.closest('.cx-workshop-cf-close')) closeWorkshop();
      });
      const frame = overlay.querySelector(`#${FRAME_ID}`);
      frame.srcdoc = frameHtml();
      state.frameWindow = frame.contentWindow;
    }
  }

  function setHostScrollLocked(locked) {
    hostDocument.documentElement?.classList.toggle('cx-workshop-cf-lock', !!locked);
    hostDocument.body?.classList.toggle('cx-workshop-cf-lock', !!locked);
  }

  function openWorkshop() {
    ensureDom();
    const overlay = hostDocument.getElementById(OVERLAY_ID);
    overlay.classList.add('is-open');
    setHostScrollLocked(true);
    sendState(false).catch(error => {
      postToFrame('cx_workshop_error', { message: error.message || String(error) });
    });
  }

  function closeWorkshop() {
    hostDocument.getElementById(OVERLAY_ID)?.classList.remove('is-open');
    setHostScrollLocked(false);
  }

  async function handleFrameMessage(event) {
    const frame = hostDocument.getElementById(FRAME_ID);
    if (!frame || event.source !== frame.contentWindow) return;
    const data = event.data || {};
    const type = data.type;
    const payload = data.payload || {};
    try {
      if (type === 'cx_workshop_ready') {
        state.frameWindow = frame.contentWindow;
        await sendState(false);
      } else if (type === 'cx_workshop_refresh') {
        postToFrame('cx_workshop_busy', { message: '正在刷新目录...' });
        await sendState(true);
        postToFrame('cx_workshop_result', { success: true, message: '目录已刷新' });
      } else if (type === 'cx_workshop_save_api') {
        const apiBase = setApiBase(payload.apiBase);
        postToFrame('cx_workshop_busy', { message: '正在连接 Cloudflare Worker...' });
        await sendState(true);
        postToFrame('cx_workshop_result', { success: true, message: `已保存地址：${apiBase}` });
      } else if (type === 'cx_workshop_install') {
        postToFrame('cx_workshop_busy', { message: '正在订阅模块...' });
        const message = await installModule(payload.moduleId);
        toast('success', message);
        await sendState(true);
        postToFrame('cx_workshop_result', { success: true, message });
      } else if (type === 'cx_workshop_uninstall') {
        postToFrame('cx_workshop_busy', { message: '正在取消订阅...' });
        const message = await uninstallModule(payload.moduleId);
        toast('success', message);
        await sendState(true);
        postToFrame('cx_workshop_result', { success: true, message });
      } else if (type === 'cx_workshop_cleanup_orphans') {
        postToFrame('cx_workshop_busy', { message: '正在清理已下架模块...' });
        const message = await cleanupOrphanModules(payload.moduleIds);
        toast('success', message);
        await sendState(true);
        postToFrame('cx_workshop_result', { success: true, message });
      } else if (type === 'cx_workshop_submit') {
        postToFrame('cx_workshop_busy', { message: '正在提交审核...' });
        const result = await submitModule(payload.submission);
        const roleCount = await syncSubmissionLocally(payload.submission);
        const message = `${result.message || `已提交审核：${result.submissionId || ''}`}${roleCount ? `；已本地同步 ${roleCount} 名主要 NPC` : ''}`;
        toast('success', message);
        await sendState(true);
        postToFrame('cx_workshop_result', { success: true, message, clearSubmit: true });
      }
    } catch (error) {
      const message = error.message || String(error);
      toast('error', message);
      postToFrame('cx_workshop_result', { success: false, message });
    }
  }

  function cleanup() {
    hostWindow.removeEventListener('message', handleFrameMessage);
    if (state.avatarRegexSyncTimer) {
      hostWindow.clearTimeout(state.avatarRegexSyncTimer);
      state.avatarRegexSyncTimer = null;
    }
    setHostScrollLocked(false);
    hostDocument.getElementById(OVERLAY_ID)?.remove();
    hostDocument.getElementById(ROOT_ID)?.remove();
    hostDocument.getElementById(STYLE_ID)?.remove();
    state.initialized = false;
  }

  if (!state.initialized) {
    state.initialized = true;
    ensureDom();
    hostWindow.addEventListener('message', handleFrameMessage);
    $(window).on('pagehide', cleanup);
    [300, 2000].forEach(delay => {
      setTimeout(() => {
        migrateLegacySharedWorkshopRoles().catch(error => {
          console.warn('[苍玄界创意工坊] 旧版角色来源迁移失败', error);
        });
      }, delay);
    });
    [0, 1000, 3000, 7000, 12000].forEach(delay => {
      setTimeout(() => {
        removeCustomRolesByNames(MISTAKEN_CUSTOM_ROLE_NAMES).catch(error => {
          console.warn('[苍玄界创意工坊] 误写主要 NPC 残留清理失败', error);
        });
      }, delay);
    });
    console.log(`[苍玄界创意工坊] loaded ${CX_WORKSHOP_BUILD_ID}`);
  }
});
